159	(function(){
160	  var LAYOUT_KEY = 'coach888_layout';
161	
162	  function renumber(grid){
163	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
164	    var title = grid.previousElementSibling;
165	    if (title && title.classList.contains('section-title')) {
166	      var countEl = title.querySelector('.count');
167	      if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
168	    }
169	  }
170	
171	  function saveLayout(){
172	    var layout = {};
173	    document.querySelectorAll('.grid').forEach(function(grid){
174	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
175	    });
176	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
177	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
178	    document.querySelectorAll('.grid').forEach(function(grid){
179	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
180	    });
181	  }
182	
183	  function loadLayout(){
184	    var raw = localStorage.getItem(LAYOUT_KEY);
185	    if (raw) {
186	      try { return JSON.parse(raw); } catch(e){}
187	    }
188	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
189	    var legacy = {}, found = false;
190	    document.querySelectorAll('.grid').forEach(function(grid){
191	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
192	      if (old) {
193	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
194	      }
195	    });
196	    return found ? legacy : null;
197	  }
198	
199	  function applyLayout(){
200	    var layout = loadLayout();
201	    if (!layout) return;
202	    var allItems = {};
203	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
204	    document.querySelectorAll('.grid').forEach(function(grid){
205	      var ids = layout[grid.dataset.section];
206	      if (!ids) return;
207	      ids.forEach(function(id){
