213	  function getDragAfterElement(grid, y){
214	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
215	    return els.reduce(function(closest, child){
216	      var box = child.getBoundingClientRect();
217	      var offset = y - box.top - box.height / 2;
218	      if (offset < 0 && offset > closest.offset) {
219	        return { offset: offset, element: child };
220	      }
221	      return closest;
222	    }, { offset: -Infinity, element: null }).element;
223	  }
224	
225	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
226	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
227	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
228	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
229	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
230	  // 拖放機制，也就不會有這個衝突。
231	  var dragEl = null;
232	  var sourceGrid = null;
233	
234	  function onMouseMove(e){
235	    if (!dragEl) return;
236	    var el = document.elementFromPoint(e.clientX, e.clientY);
237	    var targetGrid = el ? el.closest('.grid') : null;
238	    if (!targetGrid) return;
239	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
240	    if (afterEl == null) {
241	      targetGrid.appendChild(dragEl);
242	    } else if (afterEl !== dragEl) {
243	      targetGrid.insertBefore(dragEl, afterEl);
244	    }
245	  }
246	
247	  function onMouseUp(){
248	    if (!dragEl) return;
249	    dragEl.classList.remove('dragging');
250	    var targetGrid = dragEl.closest('.grid');
251	    renumber(sourceGrid);
252	    if (targetGrid !== sourceGrid) renumber(targetGrid);
253	    saveLayout();
254	    dragEl = null;
255	    sourceGrid = null;
256	    document.removeEventListener('mousemove', onMouseMove);
257	    document.removeEventListener('mouseup', onMouseUp);
258	  }
259	
260	  applyLayout();
261	
262	  document.querySelectorAll('.item').forEach(function(item){
263	    var handle = item.querySelector('.drag-handle');
264	    handle.addEventListener('mousedown', function(e){
265	      e.preventDefault();
266	      dragEl = item;
267	      sourceGrid = item.closest('.grid');
268	      item.classList.add('dragging');
269	      document.addEventListener('mousemove', onMouseMove);
270	      document.addEventListener('mouseup', onMouseUp);
271	    });
272	  });
273	
274	  document.querySelectorAll('.grid').forEach(renumber);
